BEGIN;

-- Seed target:
-- - Recruiter user seeded by IdentitySeeder: cccccccc-cccc-cccc-cccc-cccccccccccc
-- - If that recruiter has no recruiter profile yet, this script creates one.
-- - If that recruiter already has a recruiter profile, this script reuses its CompanyId
--   so the seeded jobs appear in that recruiter's scoped workspace.
--
-- Important compatibility notes:
-- - The backend normally derives DescriptionEmbeddingJson via the ONNX embedding service.
--   This SQL uses a small synthetic jsonb array instead. The current codebase does not read
--   this field for job listing/detail flows, but semantic/ML workflows may expect the backend
--   to regenerate it later.
-- - The backend normally derives JobDescriptionStructuredJson from the request payload.
--   This SQL reproduces that structure directly.
-- - The backend normally snapshots CompanyNameSnapshot / CompanyEmailSnapshot from the active
--   recruiter company. This SQL does the same from the selected target company.

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM users
        WHERE "Id" = 'cccccccc-cccc-cccc-cccc-cccccccccccc'::uuid
    ) THEN
        RAISE EXCEPTION
            'Required recruiter user % was not found. Start the API once so IdentitySeeder can create default users, or create the recruiter account first.',
            'cccccccc-cccc-cccc-cccc-cccccccccccc';
    END IF;
END $$;

INSERT INTO companies (
    "Id",
    "Name",
    "PrimaryEmail",
    "Location",
    "IsActive",
    "CreatedAtUtc",
    "UpdatedAtUtc"
)
VALUES (
    'dddddddd-dddd-dddd-dddd-dddddddddddd'::uuid,
    'NexSkill Talent Labs',
    'talent@nexskill.local',
    'Singapore',
    TRUE,
    TIMESTAMPTZ '2026-03-01 09:00:00+00',
    TIMESTAMPTZ '2026-03-27 09:00:00+00'
)
ON CONFLICT ("Id") DO UPDATE
SET
    "Name" = EXCLUDED."Name",
    "PrimaryEmail" = EXCLUDED."PrimaryEmail",
    "Location" = EXCLUDED."Location",
    "IsActive" = EXCLUDED."IsActive",
    "UpdatedAtUtc" = EXCLUDED."UpdatedAtUtc";

INSERT INTO recruiter_profiles (
    "Id",
    "UserId",
    "CompanyId",
    "CreatedAtUtc"
)
SELECT
    'eeeeeeee-eeee-eeee-eeee-eeeeeeeeeeee'::uuid,
    'cccccccc-cccc-cccc-cccc-cccccccccccc'::uuid,
    'dddddddd-dddd-dddd-dddd-dddddddddddd'::uuid,
    TIMESTAMPTZ '2026-03-01 09:05:00+00'
WHERE NOT EXISTS (
    SELECT 1
    FROM recruiter_profiles
    WHERE "UserId" = 'cccccccc-cccc-cccc-cccc-cccccccccccc'::uuid
);

WITH target_profile AS (
    SELECT rp."CompanyId" AS company_id
    FROM recruiter_profiles rp
    WHERE rp."UserId" = 'cccccccc-cccc-cccc-cccc-cccccccccccc'::uuid
    ORDER BY rp."CreatedAtUtc"
    LIMIT 1
),
target_company AS (
    SELECT
        c."Id" AS company_id,
        c."Name" AS company_name,
        c."PrimaryEmail" AS company_email
    FROM companies c
    WHERE c."Id" = COALESCE(
        (SELECT company_id FROM target_profile),
        'dddddddd-dddd-dddd-dddd-dddddddddddd'::uuid
    )
),
seed_data (
    id,
    title,
    description,
    responsibilities,
    required_skills,
    preferred_skills,
    experience_level,
    min_years,
    education,
    department,
    benefits,
    salary_min,
    salary_max,
    currency,
    location,
    schedule,
    work_setup,
    employment_type,
    status,
    number_of_vacancies,
    created_at_utc,
    posted_date_utc
) AS (
    VALUES
