INSERT INTO jobs (
    "Id","CompanyId","RecruiterId","Title","Description","DescriptionEmbeddingJson","ResponsibilitiesText","RequiredSkillsJson","PreferredSkillsJson","ExperienceLevel","MinYears","Education","Department","Benefits","SalaryMinPerAnnum","SalaryMaxPerAnnum","Currency","Location","Schedule","WorkSetup","EmploymentType","PostedDateUtc","CompanyNameSnapshot","CompanyEmailSnapshot","JobDescriptionStructuredJson","NumberOfVacancies","Status","CreatedAtUtc"
)
SELECT
    s.id,
    tc.company_id,
    'cccccccc-cccc-cccc-cccc-cccccccccccc'::uuid,
    s.title,
    s.description,
    jsonb_build_array(
        ROUND(((COALESCE(s.min_years, 0) + 1)::numeric / 10), 2),
        ROUND(((s.work_setup + 1)::numeric / 10), 2),
        ROUND(((s.employment_type + 1)::numeric / 10), 2)
    ),
    array_to_string(s.responsibilities, E'\n'),
    to_jsonb(s.required_skills),
    to_jsonb(s.preferred_skills),
    s.experience_level,
    s.min_years,
    s.education,
    s.department,
    array_to_string(s.benefits, E'\n'),
    s.salary_min,
    s.salary_max,
    s.currency,
    s.location,
    s.schedule,
    s.work_setup,
    s.employment_type,
    s.posted_date_utc,
    tc.company_name,
    tc.company_email,
    jsonb_build_object(
        'Title', s.title,
        'Description', s.description,
        'Responsibilities', to_jsonb(s.responsibilities),
        'RequiredSkills', to_jsonb(s.required_skills),
        'PreferredSkills', to_jsonb(s.preferred_skills),
        'MinimumYearsExperience', COALESCE(s.min_years, 0),
        'MinimumEducationLevel', COALESCE(s.education, ''),
        'EducationRequirements', CASE
            WHEN s.education IS NULL OR btrim(s.education) = '' THEN '[]'::jsonb
            ELSE jsonb_build_array(s.education)
        END,
        'Metadata', jsonb_build_object('experience_level', COALESCE(s.experience_level, ''))
    ),
    s.number_of_vacancies,
    s.status,
    s.created_at_utc
FROM seed_data s
CROSS JOIN target_company tc
ON CONFLICT ("Id") DO NOTHING;

COMMIT;
